import 'dart:convert';\n\nimport 'package:dio/dio.dart';\nimport 'package:flutter_dotenv/flutter_dotenv.dart';\n\n/// Servicio de Traducción usando Google Translate API\n///\n/// Google Translate ofrece:\n/// - 500,000 caracteres/mes GRATIS\n/// - $300 crédito inicial Google Cloud\n/// - 100+ idiomas soportados\n///\n/// Alternativas gratis:\n/// - DeepL API: 500,000 chars/mes gratis\n/// - Libretranslate: Open source, self-hosted\nclass TranslationService {\n  static const String _translateUrl = 'https://translation.googleapis.com/language/translate/v2';\n  \n  final Dio _dio;\n  final String _apiKey;\n  \n  TranslationService({\n    Dio? dio,\n    String? apiKey,\n  }) : _dio = dio ?? Dio(),\n       _apiKey = apiKey ?? dotenv.env['GOOGLE_CLOUD_API_KEY'] ?? '';\n  \n  /// Traducir texto\n  /// \n  /// [text]: Texto a traducir\n  /// [targetLang]: Idioma destino (es, en, pt, etc.)\n  /// [sourceLang]: Idioma origen (auto-detecta si es null)\n  Future<String> translateText({\n    required String text,\n    required String targetLang,\n    String? sourceLang,\n  }) async {\n    if (_apiKey.isEmpty) {\n      // Fallback: retornar texto original con marca de no traducido\n      return '$text [traducción no disponible - configura API key]';\n    }\n    \n    try {\n      final response = await _dio.post<Map<String, dynamic>>(\n        '$_translateUrl?key=$_apiKey',\n        data: {\n          'q': text,\n          'target': targetLang,\n          if (sourceLang != null) 'source': sourceLang,\n          'format': 'text',\n        },\n        options: Options(\n          headers: {\n            'Content-Type': 'application/json',\n          },\n        ),\n      );\n      \n      final data = response.data;\n      if (data == null || data['data'] == null) {\n        throw Exception('Error en traducción');\n      }\n      \n      final translations = data['data']['translations'] as List<dynamic>;\n      if (translations.isEmpty) {\n        return text;\n      }\n      \n      return translations.first['translatedText'] as String;\n      \n    } on DioException catch (e) {\n      if (e.response?.statusCode == 403) {\n        throw Exception('API Key inválida o sin créditos');\n      }\n      \n      // Fallback: usar traducción simple de diccionario\n      return _simpleFallbackTranslation(text, targetLang);\n    }\n  }\n  \n  /// Traducir líneas de letras con preservación de estructura\n  Future<List<String>> translateLyrics({\n    required List<String> lines,\n    required String targetLang,\n    String? sourceLang,\n  }) async {\n    if (_apiKey.isEmpty) {\n      return lines; // No traducir\n    }\n    \n    try {\n      // Traducir todas las líneas en batch (Google soporta hasta 128 textos)\n      final response = await _dio.post<Map<String, dynamic>>(\n        '$_translateUrl?key=$_apiKey',\n        data: {\n          'q': lines,\n          'target': targetLang,\n          if (sourceLang != null) 'source': sourceLang,\n          'format': 'text',\n        },\n      );\n      \n      final data = response.data;\n      if (data == null || data['data'] == null) {\n        return lines;\n      }\n      \n      final translations = data['data']['translations'] as List<dynamic>;\n      return translations\n          .map<String>((t) => t['translatedText'] as String? ?? '')\n          .toList();\n      \n    } catch (e) {\n      // Fallback: traducir línea por línea\n      final translatedLines = <String>[];\n      for (final line in lines) {\n        try {\n          final translated = await translateText(\n            text: line,\n            targetLang: targetLang,\n            sourceLang: sourceLang,\n          );\n          translatedLines.add(translated);\n        } catch (_) {\n          translatedLines.add(line);\n        }\n      }\n      return translatedLines;\n    }\n  }\n  \n  /// Detectar idioma del texto\n  Future<String> detectLanguage(String text) async {\n    if (_apiKey.isEmpty) {\n      return 'es'; // Default español\n    }\n    \n    try {\n      final response = await _dio.post<Map<String, dynamic>>(\n        '$_translateUrl/detect?key=$_apiKey',\n        data: {\n          'q': text,\n        },\n      );\n      \n      final data = response.data;\n      if (data == null || data['data'] == null) {\n        return 'es';\n      }\n      \n      final detections = data['data']['detections'] as List<dynamic>;\n      if (detections.isNotEmpty) {\n        final firstDetection = detections.first as List<dynamic>;\n        if (firstDetection.isNotEmpty) {\n          return firstDetection.first['language'] as String;\n        }\n      }\n      \n      return 'es';\n    } catch (e) {\n      return 'es';\n    }\n  }\n  \n  /// Traducción simple de fallback (diccionario básico)\n  String _simpleFallbackTranslation(String text, String targetLang) {\n    if (targetLang == 'es') {\n      // Palabras comunes inglés → español\n      final dict = {\n        'love': 'amor',\n        'heart': 'corazón',\n        'night': 'noche',\n        'day': 'día',\n        'you': 'tú',\n        'me': 'yo',\n        'and': 'y',\n        'the': 'el/la',\n        'to': 'a',\n        'in': 'en',\n        'of': 'de',\n        'is': 'es',\n        'are': 'son',\n        'for': 'para',\n        'with': 'con',\n        'on': 'en',\n        'at': 'en',\n        'by': 'por',\n        'from': 'desde',\n        'my': 'mi',\n        'your': 'tu',\n        'his': 'su',\n        'her': 'su',\n        'our': 'nuestro',\n        'their': 'su',\n        'this': 'este',\n        'that': 'ese',\n        'these': 'estos',\n        'those': 'esos',\n      };\n      \n      // Reemplazar palabras comunes\n      String translated = text.toLowerCase();\n      dict.forEach((key, value) {\n        translated = translated.replaceAll(' $key ', ' $value ');\n        translated = translated.replaceAll(' $key.', ' $value.');\n        translated = translated.replaceAll(' $key,', ' $value,');\n      });\n      \n      return translated.isNotEmpty ? translated : text;\n    }\n    \n    return text;\n  }\n  \n  /// Obtener lista de idiomas soportados\n  Future<List<Language>> getSupportedLanguages() async {\n    if (_apiKey.isEmpty) {\n      return _defaultLanguages();\n    }\n    \n    try {\n      final response = await _dio.get<Map<String, dynamic>>(\n        '$_translateUrl/languages?key=$_apiKey',\n      );\n      \n      final data = response.data;\n      if (data == null || data['data'] == null) {\n        return _defaultLanguages();\n      }\n      \n      final languages = data['data']['languages'] as List<dynamic>;\n      return languages\n          .map<Language>((lang) => Language(\n                code: lang['language'] as String,\n                name: lang['name'] as String,\n              ))\n          .toList();\n    } catch (e) {\n      return _defaultLanguages();\n    }\n  }\n  \n  List<Language> _defaultLanguages() {\n    return [\n      Language(code: 'es', name: 'Español'),\n      Language(code: 'en', name: 'English'),\n      Language(code: 'pt', name: 'Português'),\n      Language(code: 'fr', name: 'Français'),\n      Language(code: 'de', name: 'Deutsch'),\n      Language(code: 'it', name: 'Italiano'),\n    ];\n  }\n}\n\n/// Idioma soportado\nclass Language {\n  final String code;\n  final String name;\n  \n  Language({\n    required this.code,\n    required this.name,\n  });\n}\n